@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Nunito:wght@500;600;700;800;900&display=swap');
:root{--ink:#33443a;--muted:#879187;--green:#638b67;--green-dark:#456e51;--paper:#fbfaf6;--line:#edece4;--coral:#df896d;--gold:#dda84e}*{box-sizing:border-box}body{margin:0;background:#f6f4ec;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px;min-height:100vh;background-image:radial-gradient(#d8ddce 0.65px,transparent .65px);background-size:18px 18px}.app-shell{max-width:1180px;margin:auto;padding:0 32px}.topbar{height:72px;display:flex;align-items:center;border-bottom:1px solid #e8e7de;gap:18px}.brand{display:flex;align-items:center;gap:9px;color:#425b46;font:800 21px 'Nunito',sans-serif;text-decoration:none;letter-spacing:-.7px}.brand-light{font-weight:600;color:#93a38e}.brand-mark{display:grid;place-items:center;width:32px;height:32px;border-radius:11px;background:#e8efdf;color:#71916d;font-size:21px}.top-note{margin-left:auto;color:#92988b;font-size:12px;display:flex;gap:8px;align-items:center}.sun-dot{width:7px;height:7px;border-radius:50%;background:#e8b957;box-shadow:0 0 0 3px #f4ebcf}.icon-button{width:34px;height:34px;border:1px solid var(--line);border-radius:11px;background:#fff;color:#758b72;font-size:17px;cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(290px,.92fr);gap:30px;padding:27px 0 25px}.farm-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.55px;color:#9da398;margin:0 0 7px}.farm-heading h1{font:800 23px 'Nunito',sans-serif;margin:0;letter-spacing:-.4px}.wave{font-size:19px;color:#e7ad4a;vertical-align:2px;margin-left:4px}.weather-pill{background:#fff;border:1px solid var(--line);border-radius:20px;padding:7px 11px;color:#848e84;font-size:11px;display:flex;align-items:center;gap:7px}.weather-pill span:first-child{font-size:13px}.scene-card,.day-card,.seed-card,.inventory-card{background:var(--paper);border:1px solid #e9e9df;border-radius:16px;box-shadow:0 5px 16px #7776530b}.scene-card{padding:14px 14px 0;overflow:hidden}.scene-topline{display:flex;justify-content:space-between;align-items:center;padding:0px 3px 12px}.scene-location{font-weight:700;font-size:12px;color:#68776a}.pin{font-size:15px;color:#a6b694;margin-right:5px}.season-tag{color:#75926d;background:#eef2e7;border-radius:6px;padding:5px 8px;font-size:9px;font-weight:800;letter-spacing:1px}.farm-scene{height:330px;position:relative;overflow:hidden;border-radius:10px 10px 0 0;background:linear-gradient(180deg,#c7e4d7 0%,#d4ebd9 41%,#e0e9c9 42%,#b5cf91 66%,#abc480 100%)}.scene-sun{position:absolute;width:43px;height:43px;border-radius:50%;background:#ffe5a0;top:31px;right:14%;box-shadow:0 0 0 9px #ffe5a029,0 0 38px #ffe6aa8c}.cloud{position:absolute;height:13px;width:58px;border-radius:20px;background:#fff9eccc;top:46px;left:15%;opacity:.9}.cloud:before,.cloud:after{content:'';position:absolute;background:inherit;border-radius:50%;bottom:3px}.cloud:before{width:24px;height:24px;left:9px}.cloud:after{width:18px;height:18px;left:26px}.cloud-two{left:52%;top:81px;transform:scale(.7);opacity:.65}.scene-hill{position:absolute;bottom:104px;width:80%;height:130px;border-radius:50% 50% 0 0/76% 76% 0 0}.hill-back{left:-9%;background:#9fbe98}.hill-front{right:-19%;bottom:91px;height:145px;background:#8eb286}.tree{position:absolute;bottom:119px;width:42px;height:72px;z-index:1}.tree i{position:absolute;bottom:0;left:19px;width:7px;height:31px;background:#9c7854;border-radius:3px}.tree b{position:absolute;bottom:22px;left:0;width:42px;height:43px;background:#769e70;border-radius:53% 47% 50% 50%;box-shadow:inset -7px -5px #6d9469}.tree-one{left:13%;transform:scale(.94)}.tree-two{right:11%;bottom:133px;transform:scale(.72)}.tree-two b{background:#89a976}.garden{position:absolute;z-index:3;left:50%;top:49%;transform:translate(-50%,-40%);width:min(54%,410px);aspect-ratio:1.63;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:6px;padding:7px;background:#a87d59;border:5px solid #c4986a;border-radius:5px;box-shadow:0 7px 0 #805f44,0 12px 18px #3b54392a}.plot{position:relative;min-width:0;border:1px solid #8a6348;border-radius:4px;background:linear-gradient(145deg,#946d4d,#a77b54);box-shadow:inset 0 2px 3px #704d3a66;cursor:pointer;padding:0;display:grid;place-items:center;color:#fff4d5;transition:filter .15s,transform .15s;overflow:hidden}.plot:hover{filter:brightness(1.12);transform:scale(1.025);z-index:2}.plot:focus-visible{outline:2px solid #fff3b1;outline-offset:1px}.plot.watered{background:linear-gradient(145deg,#685c4b,#8a6e53)}.plot .crop-art{font-size:clamp(23px,3.8vw,39px);line-height:1;filter:drop-shadow(0 3px 1px #604d3480);position:relative;z-index:1}.plot .stage-label{position:absolute;bottom:3px;right:4px;color:#f8eaca;font-size:8px;text-shadow:0 1px #493726}.plot .water-mark{position:absolute;top:3px;right:4px;font-size:12px;color:#bce9e8}.plot.empty:after{content:'+';display:grid;place-items:center;border-radius:50%;width:21px;height:21px;color:#e5cda9;background:#fff1d112;font-size:16px;opacity:.7}.plot.watered:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(130deg,transparent 0 14px,#c9d2c414 15px 16px)}.fence{position:absolute;height:13px;left:18%;right:18%;z-index:2;opacity:.8;background:repeating-linear-gradient(90deg,transparent 0 18px,#d8bb8d 18px 22px,transparent 22px 33px);border-top:2px solid #d8bb8d;border-bottom:2px solid #d8bb8d}.fence-top{top:26%}.fence-bottom{bottom:19%;opacity:.6;z-index:1}.scene-flower{position:absolute;z-index:3;color:#f6eaaa;font-size:16px;text-shadow:0 2px #84a36c}.flower-one{left:23%;bottom:17%}.flower-two{right:22%;bottom:24%;font-size:12px}.flower-three{left:12%;bottom:24%;font-size:11px}.scene-caption{position:absolute;bottom:11px;left:0;right:0;text-align:center;color:#69805f;font:700 10px 'Nunito',sans-serif;letter-spacing:.3px;z-index:3}.caption-sparkle{color:#edf1c5;margin:0 4px}.scene-footer{height:39px;display:flex;align-items:center;gap:19px;color:#969b91;font-size:10px}.scene-footer>span{display:flex;align-items:center;gap:6px}.legend-dot{width:8px;height:8px;border-radius:50%}.dirt-dot{background:#ae8764}.water-dot{background:#83b8bb}.season-progress{margin-left:auto}.progress-track{height:4px;width:51px;border-radius:4px;background:#e9e9df;overflow:hidden}.progress-track i{height:100%;display:block;background:#9eb68a;border-radius:4px;transition:width .3s}.toolbar-wrap{margin-top:22px}.toolbar-label{display:flex;align-items:baseline;justify-content:space-between}.toolbar-label .eyebrow{margin-bottom:10px}.tool-hint{font-size:10px;color:#a2a59c}.toolbar{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.tool-card{position:relative;border:1px solid #e9e9df;background:#fbfaf6;border-radius:12px;min-height:77px;cursor:pointer;color:var(--ink);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;transition:.15s;padding:8px 3px}.tool-card:hover{transform:translateY(-2px);border-color:#c8d6bd}.tool-card.active{background:#edf3e8;border-color:#94b38b;box-shadow:0 0 0 2px #8cae7c21}.tool-emoji{font-size:23px;line-height:1}.tool-name{font-size:10px;font-weight:700}.tool-cost{position:absolute;right:5px;top:5px;font-size:8px;color:#ac9062;background:#f7f0dc;border-radius:8px;padding:2px 4px}.side-column{display:flex;flex-direction:column;gap:12px;padding-top:1px}.day-card{padding:16px 17px 14px;background:#fdfcf8}.day-head{display:flex;align-items:center;justify-content:space-between}.day-head .eyebrow,.section-heading .eyebrow{margin-bottom:4px}.day-head h2,.section-heading h2{font:800 15px 'Nunito',sans-serif;margin:0;color:#435347}.day-stamp{width:39px;height:39px;display:grid;place-items:center;border-radius:12px;background:#f5edda;color:#c59b4f;font:800 17px 'Nunito',sans-serif;transform:rotate(3deg)}.day-stats{display:grid;grid-template-columns:1fr;gap:6px;padding:13px 0 12px}.stat{display:flex;align-items:center;gap:8px}.stat-icon{display:grid;place-items:center;width:26px;height:26px;background:#edf2e8;border-radius:8px;color:#74936d;font-size:13px}.energy-icon{color:#d8aa4e;background:#f7f0de}.stat small{display:block;color:#a0a397;font-size:8px;letter-spacing:1px;font-weight:700;margin-bottom:2px}.stat strong{font:700 11px 'Nunito',sans-serif}.stat strong em{font-size:9px;color:#b9914d;font-style:normal}.energy-track{margin-left:34px;height:5px;background:#e9ebdf;border-radius:5px;overflow:hidden}.energy-track i{height:100%;display:block;width:100%;border-radius:5px;background:linear-gradient(90deg,#a8bf8c,#85a777);transition:width .25s}.money-stat{margin-top:2px}.coin-gain{margin-left:auto;color:#73936c;font-size:10px;font-weight:700}.sleep-button{width:100%;border:none;border-radius:9px;padding:10px 12px;background:#6c8f68;color:#fff;font:700 11px 'Nunito',sans-serif;cursor:pointer;transition:background .15s}.sleep-button:hover{background:#527b59}.desktop-sleep span{float:right;font-size:14px;line-height:12px}.section-heading{display:flex;align-items:center;justify-content:space-between}.seed-card,.inventory-card{padding:15px 16px 14px}.seed-sprout,.basket-icon{color:#9aad84;font-size:25px}.helper-copy{font-size:10px;color:#999f95;margin:7px 0 10px}.seed-list{display:flex;flex-direction:column;gap:6px}.seed-item{display:flex;align-items:center;padding:7px 8px;border:1px solid #efeee6;border-radius:9px;background:#fffefa;gap:9px;min-height:46px}.seed-icon{font-size:23px;width:29px;height:29px;display:grid;place-items:center;border-radius:8px;background:#f1f3e7}.seed-info{flex:1;min-width:0}.seed-info strong{display:block;font:700 10px 'Nunito',sans-serif}.seed-info small{color:#9b9f94;font-size:9px}.seed-price{font-size:9px;font-weight:700;color:#b38b4c;white-space:nowrap}.buy-button{border:0;border-radius:7px;background:#eef2e8;color:#65815f;font:700 9px 'Nunito',sans-serif;padding:6px 8px;cursor:pointer;white-space:nowrap}.buy-button:hover{background:#dce8d4}.buy-button:disabled{opacity:.42;cursor:default}.inventory-card{padding-bottom:8px}.inventory-row{display:flex;align-items:center;gap:9px;border-top:1px solid #f0efe8;padding:9px 0}.inventory-row:first-of-type{margin-top:8px}.inventory-crop-icon{width:29px;height:29px;border-radius:8px;background:#f1f3e7;color:#9ba873;display:grid;place-items:center;font-size:17px}.seed-bag{color:#a58862;background:#f5eddf}.inventory-copy{flex:1}.inventory-copy strong{display:block;font:700 10px 'Nunito',sans-serif}.inventory-copy small{color:#9da096;font-size:9px}.inventory-total{font:800 11px 'Nunito',sans-serif;color:#70846a}.inventory-total small{font-weight:500;font-size:9px;color:#a2a498}.pouch-note{font-size:9px;font-weight:600;color:#a2a498}.quest-card{display:flex;align-items:center;gap:10px;padding:12px 14px;background:#f4f1e5;border:1px solid #ebe8d8;border-radius:12px}.quest-icon{font-size:22px;color:#c5a354}.quest-card>div{flex:1;min-width:0}.quest-card .eyebrow{font-size:8px;margin-bottom:3px}.quest-card p{margin:0 0 6px;font:700 10px 'Nunito',sans-serif}.quest-progress{height:4px;border-radius:4px;background:#e3e1d3;overflow:hidden}.quest-progress i{height:100%;width:0;display:block;background:#9eb68a;transition:width .3s}.quest-count{font:700 9px 'Nunito',sans-serif;color:#8e9687}.footer{border-top:1px solid #e7e6dd;min-height:46px;display:flex;align-items:center;justify-content:space-between;color:#9b9e93;font-size:10px}.footer>span span{color:#d59078}.reset-button{border:0;background:none;color:#a2a59b;font:500 10px 'DM Sans',sans-serif;cursor:pointer}.reset-button:hover{color:#b06e5c}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,18px);opacity:0;pointer-events:none;background:#34483a;color:#fff;border-radius:24px;padding:11px 17px;font-size:12px;box-shadow:0 5px 22px #36473840;z-index:10;transition:.22s}.toast.show{transform:translate(-50%,0);opacity:1}.modal-backdrop{position:fixed;inset:0;background:#30413766;display:grid;place-items:center;padding:20px;z-index:20;opacity:0;visibility:hidden;transition:.2s}.modal-backdrop.open{opacity:1;visibility:visible}.modal-card{position:relative;max-width:350px;width:100%;padding:29px 30px 25px;text-align:center;border-radius:19px;background:#fbfaf5;box-shadow:0 20px 70px #26362955;transform:translateY(10px);transition:.2s}.open .modal-card{transform:translateY(0)}.modal-deco{font-size:29px;color:#9cb586}.modal-card .eyebrow{margin:10px 0 5px}.modal-card h2{font:800 21px 'Nunito',sans-serif;margin:0 0 8px}.modal-card>p:not(.eyebrow){color:#828a7d;font-size:12px;line-height:1.6;margin:0 0 17px}.primary-button{border:0;border-radius:9px;background:#6c8f68;color:white;font:700 12px 'Nunito',sans-serif;padding:10px 16px;cursor:pointer}.primary-button span{margin-left:9px}.mobile-actions{display:none}
@media(max-width:850px){.app-shell{padding:0 20px}.game-layout{grid-template-columns:minmax(0,1fr) 280px;gap:18px}.farm-scene{height:300px}.scene-footer{gap:10px;font-size:9px}.scene-footer>span:nth-child(2){display:none}.scene-footer .season-progress{display:flex}.tool-hint{font-size:9px}}
@media(max-width:680px){body{background-size:16px 16px}.app-shell{padding:0 14px}.topbar{height:59px}.top-note{font-size:10px}.brand{font-size:19px}.game-layout{display:flex;flex-direction:column;padding:18px 0 20px;gap:17px}.farm-heading{margin-bottom:12px}.farm-heading h1{font-size:21px}.weather-pill{padding:6px 9px;font-size:10px}.farm-scene{height:clamp(245px,70vw,340px)}.garden{width:min(66%,390px);gap:5px;padding:6px;border-width:4px;aspect-ratio:1.51}.fence-top{top:21%}.fence-bottom{bottom:15%}.scene-hill{bottom:84px}.hill-front{bottom:70px}.tree-one{bottom:100px}.tree-two{bottom:113px}.scene-caption{font-size:9px;bottom:8px}.scene-footer{height:35px}.scene-footer>span:first-child{display:flex}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:10px}.day-card{grid-column:span 2}.seed-card,.inventory-card{min-width:0;padding:13px 12px 10px}.seed-card .section-heading h2,.inventory-card .section-heading h2{font-size:13px}.seed-list{gap:5px}.seed-item{gap:5px;padding:6px 5px}.seed-icon{width:25px;height:25px;font-size:19px}.seed-info strong{font-size:9px}.seed-info small{font-size:8px}.seed-price{font-size:8px}.buy-button{padding:5px 6px;font-size:8px}.inventory-row{gap:6px}.inventory-copy strong{font-size:9px}.inventory-total{font-size:10px}.pouch-note{font-size:8px}.quest-card{grid-column:span 2}.desktop-sleep{display:none}.mobile-actions{display:block;margin-top:12px}.mobile-actions .sleep-button{max-width:220px;display:block;margin:auto}.footer{min-height:43px;font-size:9px}.scene-sun{top:24px;right:12%}.cloud{top:38px}}
@media(max-width:390px){.app-shell{padding:0 10px}.farm-heading h1{font-size:19px}.farm-scene{height:250px}.garden{width:70%;gap:4px;padding:5px}.toolbar{gap:5px}.tool-card{min-height:70px}.tool-name{font-size:9px}.seed-card,.inventory-card{padding-left:9px;padding-right:9px}.seed-price{display:none}.scene-footer{gap:7px}.scene-footer .season-progress{gap:4px}.progress-track{width:37px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;scroll-behavior:auto!important}}

(() => {
  'use strict';

  const SEASONS = [
    { name: 'Spring', copy: 'Happy little crops for spring.', weather: 'Clear skies', icon: '☀', crops: [
      { id: 'turnip', name: 'Turnip', icon: '🥬', seed: 12, value: 24, days: 2, yield: 1 },
      { id: 'strawberry', name: 'Berry', icon: '🍓', seed: 24, value: 43, days: 3, yield: 1 },
      { id: 'tulip', name: 'Tulip', icon: '🌷', seed: 18, value: 34, days: 2, yield: 1 }
    ] },
    { name: 'Summer', copy: 'Sunshine brings the sweetest things.', weather: 'Golden sunshine', icon: '☀', crops: [
      { id: 'tomato', name: 'Tomato', icon: '🍅', seed: 15, value: 29, days: 2, yield: 1 },
      { id: 'blueberry', name: 'Blueberry', icon: '🫐', seed: 25, value: 42, days: 3, yield: 1 },
      { id: 'sunflower', name: 'Sunflower', icon: '🌻', seed: 20, value: 39, days: 2, yield: 1 }
    ] },
    { name: 'Autumn', copy: 'A crisp breeze and a golden harvest.', weather: 'Breezy & bright', icon: '🍂', crops: [
      { id: 'pumpkin', name: 'Pumpkin', icon: '🎃', seed: 24, value: 52, days: 3, yield: 1 },
      { id: 'carrot', name: 'Carrot', icon: '🥕', seed: 13, value: 26, days: 2, yield: 1 },
      { id: 'cranberry', name: 'Cranberry', icon: '🫐', seed: 19, value: 36, days: 2, yield: 1 }
    ] },
    { name: 'Winter', copy: 'Cozy winter greens for your windowsill.', weather: 'Soft snow flurries', icon: '❄', crops: [
      { id: 'cabbage', name: 'Cabbage', icon: '🥬', seed: 15, value: 30, days: 2, yield: 1 },
      { id: 'snowberry', name: 'Snowberry', icon: '🫐', seed: 23, value: 44, days: 3, yield: 1 },
      { id: 'holly', name: 'Holly', icon: '🌿', seed: 17, value: 33, days: 2, yield: 1 }
    ] }
  ];
  const TOOLS = [
    { id: 'hoe', label: 'Hoe', icon: '⛏️', cost: 'FREE' },
    { id: 'plant', label: 'Plant', icon: '🌱', cost: '' },
    { id: 'water', label: 'Water', icon: '💧', cost: 'FREE' },
    { id: 'harvest', label: 'Harvest', icon: '🧺', cost: '' },
    { id: 'clear', label: 'Clear', icon: '🪴', cost: '' }
  ];
  const freshState = () => ({ day: 1, season: 0, gold: 90, energy: 100, selectedTool: 'hoe', selectedSeed: 'turnip', seeds: { turnip: 3 }, plots: Array.from({ length: 9 }, () => ({ tilled: false, crop: null, watered: false })), harvests: 0, actionCount: 0, sound: true, goalDone: false });
  let state;
  try { state = { ...freshState(), ...JSON.parse(localStorage.getItem('little-acre-save') || '{}') }; }
  catch { state = freshState(); }
  if (!Array.isArray(state.plots) || state.plots.length !== 9) state.plots = freshState().plots;
  if (!state.seeds || typeof state.seeds !== 'object') state.seeds = { turnip: 3 };
  state.season = ((Number(state.season) || 0) % SEASONS.length + SEASONS.length) % SEASONS.length;
  state.day = Math.max(1, Math.min(7, Number(state.day) || 1));
  state.gold = Math.max(0, Number(state.gold) || 0);
  state.energy = Math.max(0, Math.min(100, Number(state.energy) || 0));

  const $ = id => document.getElementById(id);
  const garden = $('garden');
  let toastTimer;
  let audioContext;
  const season = () => SEASONS[state.season];
  const seedCount = id => Math.max(0, Number(state.seeds[id]) || 0);
  const cropInfo = id => SEASONS.flatMap(s => s.crops).find(c => c.id === id);
  const save = () => { try { localStorage.setItem('little-acre-save', JSON.stringify(state)); } catch { /* local save unavailable */ } };
  function toast(message) {
    const el = $('toast'); el.textContent = message; el.classList.add('show');
    clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2200);
  }
  function sound(freq = 550) {
    if (!state.sound) return;
    try {
      audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audioContext.createOscillator(), gain = audioContext.createGain();
      oscillator.type = 'sine'; oscillator.frequency.value = freq; gain.gain.setValueAtTime(.055, audioContext.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + .13);
      oscillator.connect(gain); gain.connect(audioContext.destination); oscillator.start(); oscillator.stop(audioContext.currentTime + .14);
    } catch { /* audio is optional */ }
  }
  function render() {
    const current = season();
    $('dateLabel').textContent = `${current.name} · Day ${state.day}`;
    $('dayStamp').textContent = String(state.day).padStart(2, '0');
    $('seasonTag').textContent = current.name.toUpperCase();
    $('weatherIcon').textContent = current.icon;
    $('weatherText').textContent = current.weather;
    $('seasonDay').textContent = `Day ${state.day} of 7`;
    $('seasonProgress').style.width = `${(state.day / 7) * 100}%`;
    $('energyLabel').textContent = `${state.energy} / 100`;
    $('energyBar').style.width = `${state.energy}%`;
    $('energyBar').style.background = state.energy < 25 ? '#d48d72' : '';
    $('goldLabel').innerHTML = `${state.gold} <em>g</em>`;
    $('seasonCopy').textContent = current.copy;
    $('seedCount').textContent = `${Object.values(state.seeds).reduce((a, n) => a + (Number(n) || 0), 0)} seeds`;
    $('harvestTotal').innerHTML = `${state.harvests} <small>crops</small>`;
    $('goalText').textContent = state.goalDone ? 'Your first little crop is in the ground!' : 'Give your first plot some love.';
    $('goalCount').textContent = state.goalDone ? '1/1' : '0/1';
    $('goalProgress').style.width = state.goalDone ? '100%' : '0%';
    $('soundBtn').textContent = state.sound ? '♫' : '♪';
    renderPlots(); renderTools(); renderSeeds();
    $('resetBtn').setAttribute('aria-label', 'Start a new save');
    save();
  }
  function renderPlots() {
    garden.replaceChildren();
    state.plots.forEach((plot, index) => {
      const button = document.createElement('button');
      button.type = 'button'; button.className = `plot${plot.tilled ? '' : ' empty'}${plot.watered ? ' watered' : ''}`;
      button.setAttribute('aria-label', plot.crop ? `${cropInfo(plot.crop.id)?.name || 'Crop'}, growth stage ${plot.crop.progress + 1} of ${cropInfo(plot.crop.id)?.days || 2}${plot.crop.progress >= (cropInfo(plot.crop.id)?.days || 2) ? ', ready to harvest' : ''}` : plot.tilled ? `Empty tilled plot ${index + 1}` : `Untilled plot ${index + 1}`);
      if (plot.crop) {
        const info = cropInfo(plot.crop.id) || season().crops[0];
        const stage = Math.min(info.days, plot.crop.progress);
        const plant = document.createElement('span'); plant.className = 'crop-art';
        plant.textContent = stage >= info.days ? info.icon : stage === 0 ? '🌱' : ['🌱', '🌿', '🌾'][Math.min(stage, 2)];
        button.append(plant);
        const label = document.createElement('span'); label.className = 'stage-label'; label.textContent = stage >= info.days ? 'READY!' : `${stage}/${info.days}`; button.append(label);
      }
      if (plot.watered) { const mark = document.createElement('span'); mark.className = 'water-mark'; mark.textContent = '✦'; button.append(mark); }
      button.addEventListener('click', () => useTool(index));
      garden.append(button);
    });
  }
  function renderTools() {
    const toolbar = $('toolbar'); toolbar.replaceChildren();
    TOOLS.forEach(tool => {
      const button = document.createElement('button'); button.type = 'button'; button.className = `tool-card${state.selectedTool === tool.id ? ' active' : ''}`;
      button.setAttribute('aria-pressed', String(state.selectedTool === tool.id));
      button.innerHTML = `${tool.cost ? `<span class="tool-cost">${tool.cost}</span>` : ''}<span class="tool-emoji">${tool.icon}</span><span class="tool-name">${tool.label}</span>`;
      button.addEventListener('click', () => { state.selectedTool = tool.id; sound(460); render(); }); toolbar.append(button);
    });
  }
  function renderSeeds() {
    const list = $('seedList'); list.replaceChildren();
    season().crops.forEach(crop => {
      const row = document.createElement('div'); row.className = 'seed-item';
      const icon = document.createElement('span'); icon.className = 'seed-icon'; icon.textContent = crop.icon;
      const info = document.createElement('span'); info.className = 'seed-info'; info.innerHTML = `<strong>${crop.name} seed</strong><small>${crop.days} days · sells for ${crop.value}g</small>`;
      const price = document.createElement('span'); price.className = 'seed-price'; price.textContent = `${crop.seed}g`;
      const buy = document.createElement('button'); buy.className = 'buy-button'; buy.type = 'button'; buy.textContent = seedCount(crop.id) ? `Have ${seedCount(crop.id)}` : 'Buy'; buy.disabled = state.gold < crop.seed;
      buy.setAttribute('aria-label', `Buy ${crop.name} seed for ${crop.seed} gold`);
      buy.addEventListener('click', () => buySeed(crop)); row.append(icon, info, price, buy); list.append(row);
    });
  }
  function spendEnergy(amount) {
    if (state.energy < amount) { toast('You’re tuckered out. End the day to rest!'); return false; }
    state.energy -= amount; return true;
  }
  function useTool(index) {
    const plot = state.plots[index];
    if (state.selectedTool === 'hoe') {
      if (plot.tilled) return toast('This little plot is already ready.');
      if (!spendEnergy(5)) return;
      plot.tilled = true; toast('A fresh patch, ready for something lovely.');
    } else if (state.selectedTool === 'plant') {
      const id = state.selectedSeed, crop = cropInfo(id);
      if (!crop || !seedCount(id)) return toast('Pick up some seasonal seeds first.');
      if (!plot.tilled) return toast('Give this plot a little hoe first.');
      if (plot.crop) return toast('Something is already growing here.');
      if (!spendEnergy(3)) return;
      state.seeds[id] = seedCount(id) - 1; plot.crop = { id, progress: 0 }; plot.watered = false;
      if (!state.goalDone) state.goalDone = true;
      toast(`${crop.name} seed tucked in. Give it water and time!`); sound(660);
    } else if (state.selectedTool === 'water') {
      if (!plot.crop) return toast('Nothing to water here just yet.');
      if (plot.watered) return toast('This crop is already watered today.');
      if (!spendEnergy(2)) return;
      plot.watered = true; toast('A nice, refreshing drink.');
    } else if (state.selectedTool === 'harvest') {
      if (!plot.crop) return toast('No crop to pick here.');
      const crop = cropInfo(plot.crop.id);
      if (plot.crop.progress < (crop?.days || 2)) return toast('Not quite ripe yet. Let it grow a little longer.');
      const value = crop?.value || 20; state.gold += value; state.harvests += crop?.yield || 1;
      plot.crop = null; plot.tilled = true; plot.watered = false;
      $('coinGain').textContent = `+${value}g`; setTimeout(() => { $('coinGain').textContent = ''; }, 1200);
      toast(`Lovely! ${crop?.name || 'Crop'} sold for ${value}g.`); sound(790);
    } else if (state.selectedTool === 'clear') {
      if (!plot.tilled && !plot.crop) return toast('This patch is already clear.');
      if (!spendEnergy(2)) return;
      plot.crop = null; plot.tilled = false; plot.watered = false; toast('All cleared and ready for a fresh start.');
    }
    state.actionCount += 1; render();
  }
  function buySeed(crop) {
    if (state.gold < crop.seed) return toast('Not quite enough gold for those seeds.');
    state.gold -= crop.seed; state.seeds[crop.id] = seedCount(crop.id) + 1; state.selectedSeed = crop.id; state.selectedTool = 'plant';
    toast(`${crop.name} seed added to your pouch. Tap a plot to plant!`); sound(620); render();
  }
  function sleep() {
    const oldSeason = season().name;
    let grown = 0;
    state.plots.forEach(plot => {
      if (plot.crop && plot.crop.progress < (cropInfo(plot.crop.id)?.days || 2)) {
        // A crop gets a growth day when watered, or when the weather is kind.
        if (plot.watered || (state.day % 3 !== 0 && state.season !== 3)) { plot.crop.progress += 1; grown += 1; }
      }
      plot.watered = false;
    });
    state.day += 1; state.energy = 100;
    let newSeason = false;
    if (state.day > 7) { state.day = 1; state.season = (state.season + 1) % SEASONS.length; newSeason = true; }
    const modalTitle = newSeason ? `Hello, ${season().name.toLowerCase()}!` : 'A day well spent';
    let text = grown ? `${grown} little ${grown === 1 ? 'crop has' : 'crops have'} grown overnight. The morning feels full of possibility.` : 'A good night’s rest. Your energy is back, and there’s a fresh day ahead.';
    if (newSeason) text = `The days have turned from ${oldSeason.toLowerCase()} to ${season().name.toLowerCase()}. ${grown ? `${grown} crops grew overnight, too. ` : ''}A whole new season of possibilities is waiting.`;
    $('modalTitle').textContent = modalTitle; $('modalText').textContent = text;
    $('modal').classList.add('open'); $('modal').setAttribute('aria-hidden', 'false'); render(); sound(520);
  }
  $('sleepBtn').addEventListener('click', sleep);
  $('sleepBtnMobile').addEventListener('click', sleep);
  $('modalClose').addEventListener('click', () => { $('modal').classList.remove('open'); $('modal').setAttribute('aria-hidden', 'true'); render(); });
  $('modal').addEventListener('click', event => { if (event.target === $('modal')) $('modalClose').click(); });
  $('soundBtn').addEventListener('click', () => { state.sound = !state.sound; render(); toast(state.sound ? 'Sound on' : 'Sound off'); });
  $('resetBtn').addEventListener('click', () => {
    if (!window.confirm('Start a new farm? Your current save will be replaced.')) return;
    state = freshState(); render(); toast('A fresh little farm, just for you.');
  });
  document.addEventListener('keydown', event => { if (event.key === 'Escape' && $('modal').classList.contains('open')) $('modalClose').click(); });
  render();
})();

